using System;
class C
{
    static string M1(object o) => (o is int or long) ? "True" : "False";
    static string M2(object o) => (o is int || o is long) ? "True" : "False";
    public static void Main()
    {
        Console.Write(M1(1));
        Console.Write(M1(string.Empty));
        Console.Write(M1(1L));
        Console.Write(M1(1UL));
    }
}
